"""Hand-written, realistic answers (NOT generated by the templates). Run in C:\\mockmate_eval after evaluate_hr100.py works.
Checks the rule on natural text:  on-topic => score above 0,  off-topic / wrong-question => 0."""
import json, re, urllib.request

MODEL, URL = "mockmate-hr100", "http://localhost:11434/api/chat"
TASK_RE = re.compile(r"TASK:\s*(\S+)\s*\nINPUT:\s*(\{.*\})\s*\n\s*\nReturn", re.S)
india = {x["question"]: x for x in json.load(open("hr_india_100.json", encoding="utf-8"))}

# take the exact system prompt and prompt layout from the validation file
tmpl = None
for line in open("validation.jsonl", encoding="utf-8"):
    msgs = json.loads(line)["messages"]
    u = next(m["content"] for m in msgs if m["role"] == "user")
    m = TASK_RE.search(u)
    if m and m.group(1) == "evaluate_answer" and json.loads(m.group(2)).get("question") in india:
        tmpl = {"system": next(x["content"] for x in msgs if x["role"] == "system"),
                "pre": u[:m.start(2)], "suf": u[m.end(2):], "input": json.loads(m.group(2))}
        break
assert tmpl, "validation.jsonl has no HR rows - use the NEW validation file"

def ask(question, answer):
    item = india[question]; inp = dict(tmpl["input"])
    inp.update({"question": question, "answer": answer, "expectedConcepts": item["concepts"], "reference_answer": item["guidance"]})
    user = tmpl["pre"] + json.dumps(inp, indent=2, ensure_ascii=False) + tmpl["suf"]
    body = json.dumps({"model": MODEL, "stream": False, "options": {"temperature": 0, "num_predict": 700},
                       "messages": [{"role": "system", "content": tmpl["system"]}, {"role": "user", "content": user}]}).encode()
    req = urllib.request.Request(URL, body, {"Content-Type": "application/json"})
    return json.loads(json.load(urllib.request.urlopen(req, timeout=300))["message"]["content"])

TESTS = [  # (question, answer, expectation)
 ("Tell me about yourself.", "I am a final year CSE student from Coimbatore. I built a placement portal as my final year project with a team of four, and I interned at a startup where I fixed bugs in their billing module. I am looking for a role where I can grow as a software engineer.", "high"),
 ("Why should we hire you?", "I have hands-on Python and SQL experience from two internships, I learn quickly, and in my last project I cut report generation time by 40 percent. I can contribute to your analytics team from the first month.", "high"),
 ("Why should we hire you?", "I went to Goa last month and the beaches were amazing.", "zero"),
 ("What is your notice period?", "My notice period is 60 days, but my manager has agreed it can be reduced to 30 days if needed.", "positive"),
 ("What is your notice period?", "I handled the conflict by listening to both sides and finding a compromise.", "zero"),
 ("Are you willing to relocate to another city?", "Yes, I am open to relocating. I have lived in hostels in two cities during college, so I adapt quickly.", "positive"),
 ("What are your salary expectations?", "As a fresher I am looking for a package in line with market standards, around 4 to 5 LPA, but I am flexible and mainly want to learn.", "positive"),
 ("Tell me about a time you failed.", "I failed my first mock interview because I rambled. I recorded myself, practised with a friend for two weeks, and my next interview went much better.", "high"),
 ("How do you handle stress?", "Whatever.", "zero"),
 ("Where do you see yourself in five years?", "In five years I want to grow into a senior developer in your company, learn the product deeply and mentor new joiners.", "positive"),
]
ok = 0
for q, a, expect in TESTS:
    try: r = ask(q, a)
    except Exception as e: print("ERROR", q, e); continue
    s = r["score"]
    good = (s == 0 and r["isIrrelevant"]) if expect == "zero" else (s >= 50 if expect == "high" else s >= 1)
    ok += good
    print(f"[{'PASS' if good else 'CHECK'}] expect {expect:8} score={s:>3} rel={r['relevance']} irrelevant={r['isIrrelevant']} | {q[:42]} | {a[:46]}...")
print(f"\n{ok}/{len(TESTS)} as expected")
